#include "led.h"
#include "timer.h"
#include "uart.h"
#include <stdint.h>
#include <string.h>
#include "stm32c031xx.h"

int main(void)
{
    uart_init();
    timer_init();
    led_init();

    char c [10];
    char *ptr = c;

    char a;

    uart_write_string("UART ready");
    uart_write_string("\r\n");


    while (1)
    {
       if (uart_char_available())
       {
            a = uart_read_char();

            if (a == '\r' || a == '\n')
            {
                *ptr = '\0';
                uart_write_string(c);
                uart_write_string("\r\n");
                ptr = c;
            }

            if (ptr < (c + 9))
            {
                *ptr = a;
                ptr++;
            }

            if (strcmp(c, "led on"))
            {
                led_toggle();
            }

            else if (strcmp(c, "led off"))
            {
                led_toggle();
            }
            
            else if (strcmp(c, "status"))
            {
                uart_write_string("Timer: running");
                uart_write_uint(TIM3->SR);
            }
       }
    }
}